package vn.vinhkhang.warehouse;

import java.util.*;
import java.sql.*;
import java.math.BigDecimal;
import java.time.Instant;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;

/** Portable business data; credentials and machine connection settings never travel. */
@RestController @RequestMapping("/api/section-backup")
public class SectionBackup {
 private final Api core; private final JdbcTemplate db; private final ObjectMapper json;
 private final TransactionTemplate tx; private final FinanceSnapshot finance;
 private static final List<String> CATALOG=List.of("locations","vehicle_models","parts","part_color_models","suppliers","dealers","carriers","bom_versions","bom_lines");
 private static final List<String> BUSINESS=List.of("stock_documents","stock_document_lines","production_orders","production_order_lines","production_materials","production_line_materials","vehicle_receipts","vehicles","vehicle_shipments","vehicle_shipment_lines","stock_movements","retained_stock_effects","stock_balances","revenue_sales","revenue_lines","revenue_entries","sales_transfers");
 private static final Set<String> OPERATIONS=Set.of("documents","stock","production","receipts","shipments","reports","salesreport");
 private static final Map<String,String> LABELS=Map.ofEntries(Map.entry("dealers","Đại lý"),Map.entry("carriers","Nhà xe VC"),Map.entry("suppliers","Nhà cung cấp"),Map.entry("models","Mẫu xe"),Map.entry("parts","Linh kiện"),Map.entry("bom","Định mức BOM"),Map.entry("documents","Nhập / xuất linh kiện"),Map.entry("stock","Tồn kho"),Map.entry("production","Sản xuất / lắp ráp"),Map.entry("receipts","Nhập xe"),Map.entry("shipments","Xuất hàng"),Map.entry("reports","Báo cáo kho"),Map.entry("salesreport","Báo cáo doanh số"));
 public SectionBackup(Api core,JdbcTemplate db,ObjectMapper json,PlatformTransactionManager tm,FinanceSnapshot finance){this.core=core;this.db=db;this.json=json;this.tx=new TransactionTemplate(tm);this.finance=finance;}
 @ExceptionHandler(Api.Problem.class) public org.springframework.http.ResponseEntity<?> error(Api.Problem e){return org.springframework.http.ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
 @ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) public org.springframework.http.ResponseEntity<?> conflict(Exception e){return org.springframework.http.ResponseEntity.status(409).body(Map.of("message","File có dữ liệu trùng hoặc liên kết không hợp lệ. Chưa khôi phục bản ghi nào."));}
 private List<String> tables(String section){if(!LABELS.containsKey(section))throw new Api.Problem(400,"Mục sao lưu không hợp lệ");if(OPERATIONS.contains(section)){var all=new ArrayList<>(CATALOG);all.addAll(BUSINESS);return all;}return switch(section){case "parts"->List.of("vehicle_models","parts","part_color_models");case "models"->List.of("vehicle_models");case "bom"->List.of("vehicle_models","parts","part_color_models","bom_versions","bom_lines");default->List.of(section);};}
 private record Schema(List<String> columns,List<String> keys,Map<String,String> parents){}
 private Schema schema(String table){return db.execute((org.springframework.jdbc.core.ConnectionCallback<Schema>)c->{var columns=new ArrayList<String>();var keys=new TreeMap<Integer,String>();var parents=new HashMap<String,String>();try(var r=c.getMetaData().getColumns(null,"PUBLIC",table.toUpperCase(Locale.ROOT),null)){while(r.next())columns.add(r.getString("COLUMN_NAME"));}try(var r=c.getMetaData().getPrimaryKeys(null,"PUBLIC",table.toUpperCase(Locale.ROOT))){while(r.next())keys.put(r.getInt("KEY_SEQ"),r.getString("COLUMN_NAME"));}try(var r=c.getMetaData().getImportedKeys(null,"PUBLIC",table.toUpperCase(Locale.ROOT))){while(r.next())parents.put(r.getString("FKCOLUMN_NAME"),r.getString("PKTABLE_NAME").toLowerCase(Locale.ROOT));}if(columns.isEmpty()||keys.isEmpty())throw new Api.Problem(400,"Không đọc được mục dữ liệu: "+table);return new Schema(columns,new ArrayList<>(keys.values()),parents);});}
 private List<Map<String,Object>> rows(String table,boolean active){var s=schema(table);String where=active&&s.columns.contains("DELETED")?" WHERE deleted=FALSE":"";return db.query("SELECT * FROM "+table+where+" ORDER BY "+String.join(",",s.keys),(r,n)->{var row=new LinkedHashMap<String,Object>();for(String column:s.columns){Object value=r.getObject(column);if(value instanceof Clob)value=r.getString(column);else if(value!=null&&!(value instanceof Number)&&!(value instanceof Boolean))value=r.getString(column);row.put(column,value);}return row;});}
 @GetMapping("/{section}") public synchronized Object export(@RequestHeader(value="Authorization",required=false) String token,@PathVariable String section){var actor=core.admin(token);boolean ops=OPERATIONS.contains(section);var data=new LinkedHashMap<String,Object>();for(String t:tables(section))data.put(t,rows(t,!ops&&!Set.of("parts","bom").contains(section)));var packet=new LinkedHashMap<String,Object>();packet.put("format","VINHKHANG-KHO-SECTION");packet.put("version",1);packet.put("section",section);packet.put("title",LABELS.get(section));packet.put("generated_at",Instant.now().toString());packet.put("data",data);core.audit(actor,"BACKUP_SECTION",section,0);return packet;}
 @SuppressWarnings("unchecked") private Map<String,List<Map<String,Object>>> validate(String section,Map<String,Object> packet){var allowed=tables(section);if(!"VINHKHANG-KHO-SECTION".equals(packet.get("format"))||!Objects.toString(packet.get("version"),"").equals("1")||!section.equals(packet.get("section"))||!(packet.get("data") instanceof Map<?,?> raw)||!raw.keySet().equals(new HashSet<>(allowed)))throw new Api.Problem(400,"File sao lưu không đúng mục đang mở hoặc không đúng định dạng Kho");var out=new LinkedHashMap<String,List<Map<String,Object>>>();int total=0;for(String table:allowed){Object value=raw.get(table);if(!(value instanceof List<?> list))throw new Api.Problem(400,"File thiếu bảng dữ liệu");var s=schema(table);var converted=new ArrayList<Map<String,Object>>();var seen=new HashSet<String>();for(Object item:list){if(!(item instanceof Map<?,?> row)||!row.keySet().equals(new HashSet<>(s.columns)))throw new Api.Problem(400,"File không cùng cấu trúc dữ liệu. Anh cập nhật hai máy lên cùng phiên bản.");var copy=new LinkedHashMap<String,Object>((Map<String,Object>)row);for(Object v:copy.values())if(v instanceof Map<?,?>||v instanceof List<?>||v!=null&&v.toString().length()>200000)throw new Api.Problem(400,"Giá trị trong file không hợp lệ");String key=s.keys.stream().map(k->Objects.toString(copy.get(k),"null")).collect(java.util.stream.Collectors.joining("|"));if(!seen.add(key)||s.keys.stream().anyMatch(k->copy.get(k)==null))throw new Api.Problem(400,"File có khóa dữ liệu trùng hoặc rỗng");converted.add(copy);if(++total>100000)throw new Api.Problem(400,"File quá lớn; anh dùng sao lưu toàn bộ dữ liệu");}out.put(table,converted);}return out;}
 private String fingerprint(String section,Map<String,Object> packet){try{var digest=java.security.MessageDigest.getInstance("SHA-256");digest.update(json.writeValueAsBytes(packet));for(String table:tables(section))digest.update(json.writeValueAsBytes(rows(table,false)));return java.util.HexFormat.of().formatHex(digest.digest());}catch(Exception e){throw new Api.Problem(500,"Không kiểm tra được dữ liệu trước khôi phục");}}
 private long id(Object value){try{return new BigDecimal(value.toString()).longValueExact();}catch(Exception e){throw new Api.Problem(400,"Mã liên kết trong file không hợp lệ");}}
 private Object mapped(Map<String,Map<Long,Long>> ids,String table,Object old){if(old==null)return null;Long value=ids.getOrDefault(table,Map.of()).get(id(old));if(value==null)throw new Pending();return value;}
 private static class Pending extends RuntimeException{}
 private static boolean equal(Object a,Object b){if(a instanceof Number&&b instanceof Number)return new BigDecimal(a.toString()).compareTo(new BigDecimal(b.toString()))==0;return Objects.equals(a,b);}
 private Map<String,Object> restore(String section,Map<String,List<Map<String,Object>>> data,Api.Session actor){boolean ops=OPERATIONS.contains(section);if(ops)for(String t:BUSINESS)if(db.queryForObject("SELECT COUNT(*) FROM "+t,Long.class)>0)throw new Api.Problem(409,"Máy nhận đã có giao dịch hoặc tồn kho. Không gộp hai kho để tránh sai số lượng; anh dùng mục Sao lưu dữ liệu để chuyển toàn bộ hoặc chuyển riêng từng danh mục.");var ids=new HashMap<String,Map<Long,Long>>();var schemas=new HashMap<String,Schema>();for(String t:data.keySet()){schemas.put(t,schema(t));ids.put(t,new HashMap<>());}var pending=new ArrayList<Map.Entry<String,Map<String,Object>>>();data.forEach((t,rs)->rs.forEach(r->pending.add(Map.entry(t,r))));int added=0,kept=0;int initial=pending.size();while(!pending.isEmpty()){int before=pending.size();var iterator=pending.iterator();while(iterator.hasNext()){var entry=iterator.next();String t=entry.getKey();var original=entry.getValue();var s=schemas.get(t);var row=new LinkedHashMap<>(original);try{
  for(var fk:s.parents.entrySet())if(row.get(fk.getKey())!=null)row.put(fk.getKey(),fk.getValue().equals("app_users")?actor.id():mapped(ids,fk.getValue(),row.get(fk.getKey())));
  if(t.equals("revenue_sales")&&!Boolean.TRUE.equals(row.get("SOURCE_DETACHED")))row.put("SOURCE_ID",mapped(ids,"VEHICLE".equals(row.get("SOURCE_TYPE"))?"vehicle_shipments":"stock_documents",row.get("SOURCE_ID")));
  if(t.equals("revenue_lines")){var sales=data.get("revenue_sales").stream().filter(r->id(r.get("ID"))==id(original.get("SALE_ID"))).findFirst().orElseThrow(()->new Api.Problem(400,"Thiếu doanh số gốc"));if(!Boolean.TRUE.equals(sales.get("SOURCE_DETACHED"))){String source="LK".equals(row.get("CATEGORY"))?"stock_document_lines":"vehicles";var members=new ArrayList<String>();for(String member:row.get("MEMBERS").toString().split(","))members.add(mapped(ids,source,member).toString());row.put("MEMBERS",String.join(",",members));}}
  List<String> match=s.columns.contains("CODE")?List.of("CODE"):t.equals("bom_versions")?List.of("MODEL_ID","VERSION"):s.keys.equals(List.of("ID"))?List.of():s.keys;
  List<Map<String,Object>> existing=match.isEmpty()?List.of():db.queryForList("SELECT * FROM "+t+" WHERE "+match.stream().map(k->k+"=?").collect(java.util.stream.Collectors.joining(" AND ")),match.stream().map(row::get).toArray());
  if(!existing.isEmpty()){var found=existing.getFirst();if(ops||!s.columns.contains("CODE")){for(String k:s.columns)if(!k.equals("ID")&&!equal(found.get(k) instanceof java.time.temporal.TemporalAccessor?found.get(k).toString():found.get(k),row.get(k)))throw new Api.Problem(409,"Máy nhận đã có dữ liệu khác với file: "+Objects.toString(row.get("CODE"),t)+". Chưa khôi phục dòng nào.");}if(s.columns.contains("DELETED")&&Boolean.TRUE.equals(found.get("DELETED"))&&!Boolean.TRUE.equals(row.get("DELETED")))throw new Api.Problem(409,"Mã "+row.get("CODE")+" đã xóa trên máy nhận. Anh khôi phục mục đã xóa hoặc đổi mã trước.");if(s.keys.equals(List.of("ID")))ids.get(t).put(id(original.get("ID")),id(found.get("ID")));kept++;}
  else {if(s.keys.equals(List.of("ID")))row.remove("ID");var columns=new ArrayList<>(row.keySet());String sql="INSERT INTO "+t+"("+String.join(",",columns)+") VALUES("+String.join(",",Collections.nCopies(columns.size(),"?"))+")";if(s.keys.equals(List.of("ID"))){long created=core.insert(sql,columns.stream().map(row::get).toArray());ids.get(t).put(id(original.get("ID")),created);if(t.equals("revenue_sales")&&Boolean.TRUE.equals(row.get("SOURCE_DETACHED")))db.update("UPDATE revenue_sales SET source_id=? WHERE id=?",-created,created);}else db.update(sql,columns.stream().map(row::get).toArray());added++;}
  iterator.remove();
 }catch(Pending wait){}}
 if(pending.size()==before)throw new Api.Problem(400,"File thiếu dữ liệu liên quan hoặc có liên kết vòng; chưa khôi phục dòng nào.");}
 if(ops){long errors=db.queryForObject("SELECT COUNT(*) FROM stock_balances b WHERE b.quantity<>(SELECT COALESCE(SUM(h.quantity),0) FROM stock_history h WHERE h.part_id=b.part_id AND h.location_id=b.location_id)",Long.class);long missing=db.queryForObject("SELECT COUNT(*) FROM (SELECT part_id,location_id,SUM(quantity) q FROM stock_history GROUP BY part_id,location_id) h WHERE h.q<>0 AND NOT EXISTS(SELECT 1 FROM stock_balances b WHERE b.part_id=h.part_id AND b.location_id=h.location_id)",Long.class);if(errors+missing>0)throw new Api.Problem(400,"Tồn kho trong file không khớp lịch sử nhập xuất. Chưa khôi phục dữ liệu.");}
 return Map.of("added",added,"kept",kept,"total",initial,"operations",ops);
 }
 @PostMapping("/{section}/preview") public synchronized Object preview(@RequestHeader(value="Authorization",required=false) String token,@PathVariable String section,@RequestBody Map<String,Object> packet){var actor=core.admin(token);var data=validate(section,packet);String fingerprint=fingerprint(section,packet);var summary=tx.execute(status->{try{return restore(section,data,actor);}finally{status.setRollbackOnly();}});var result=new LinkedHashMap<String,Object>(summary);result.put("fingerprint",fingerprint);result.put("title",LABELS.get(section));result.put("tables",data.entrySet().stream().map(e->Map.of("name",e.getKey(),"count",e.getValue().size())).toList());return result;}
 @PostMapping("/{section}/restore") public synchronized Object execute(@RequestHeader(value="Authorization",required=false) String token,@PathVariable String section,@RequestBody Map<String,Object> body){var actor=core.admin(token);if(!"KHOI PHUC".equals(body.get("confirmation"))||!(body.get("packet") instanceof Map<?,?>))throw new Api.Problem(400,"Xác nhận khôi phục dữ liệu");@SuppressWarnings("unchecked")var packet=(Map<String,Object>)body.get("packet");var data=validate(section,packet);if(!fingerprint(section,packet).equals(body.get("fingerprint")))throw new Api.Problem(409,"Dữ liệu hoặc file đã thay đổi; anh xem lại trước khi khôi phục.");String backup=core.backup(token).get("file");try(var zip=new java.util.zip.ZipFile(backup)){if(zip.size()==0)throw new java.io.IOException();}catch(java.io.IOException e){throw new Api.Problem(500,"Chưa tạo được bản sao an toàn. Chưa khôi phục dữ liệu.");}var result=tx.execute(status->{var imported=restore(section,data,actor);core.audit(actor,"RESTORE_SECTION",section,0);return imported;});finance.publish();var answer=new LinkedHashMap<String,Object>(result);answer.put("backup",backup);return answer;}
}
